package com.desktodo.app;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Build;import org.json.*;
/** One deadline alarm per current focus session; independent of foreground polling. */
final class FocusAlarm {
 static JSONObject cfg(Context c)throws Exception{return new JSONObject(c.getSharedPreferences("mojian-native",0).getString("cfg","{}"));}
 static PendingIntent pending(Context c){return PendingIntent.getBroadcast(c,0,new Intent(c,ReminderReceiver.class).setAction("com.desktodo.app.FOCUS").setData(Uri.parse("mojian://focus/deadline")),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void reconcile(Context c,boolean force){try{JSONObject cfg=cfg(c);long end=cfg.optLong("focusEnd",0),now=System.currentTimeMillis();String key=cfg.optString("focusSession")+"|"+end;android.content.SharedPreferences p=c.getSharedPreferences("mojian-focus",0);String signature=key+ReminderScheduler.permitted(c);if(!force&&signature.equals(p.getString("signature","")))return;AlarmManager am=c.getSystemService(AlarmManager.class);am.cancel(pending(c));if(end>0&&now-end<3600000&&!key.equals(p.getString("sent",""))&&ReminderScheduler.permitted(c)){long at=Math.max(end,now+1000);if(Build.VERSION.SDK_INT<31||am.canScheduleExactAlarms())am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c));else am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,at,pending(c));}p.edit().putString("signature",signature).apply();}catch(Exception ignored){}}
 static boolean deliverable(JSONObject cfg,long now,String sent,boolean allowed){long end=cfg.optLong("focusEnd",0);return allowed&&end>0&&end<=now+1000&&now-end<=3600000&&!(cfg.optString("focusSession")+"|"+end).equals(sent);}
 static void fire(Context c){try{JSONObject cfg=cfg(c);long end=cfg.optLong("focusEnd",0),now=System.currentTimeMillis();if(end<=0||end>now+1000||now-end>3600000||!ReminderScheduler.permitted(c))return;String key=cfg.optString("focusSession")+"|"+end;android.content.SharedPreferences prefs=c.getSharedPreferences("mojian-focus",0);if(!deliverable(cfg,now,prefs.getString("sent",""),ReminderScheduler.permitted(c)))return;NotificationManager nm=c.getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("focus-done","专注完成",NotificationManager.IMPORTANCE_DEFAULT));PendingIntent open=PendingIntent.getActivity(c,1,new Intent(c,MainActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);nm.notify("focus",1,new Notification.Builder(c,"focus-done").setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle("这一段专注完成了").setContentText("起来走走，给眼睛一点休息。").setContentIntent(open).setAutoCancel(true).build());prefs.edit().putString("sent",key).commit();}catch(Exception ignored){}}
}
